from pathlib import Path
import json,re
clauses=json.loads(Path('research/clauses.json').read_text(encoding='utf-8'))
pages=json.loads(Path('research/pages.json').read_text(encoding='utf-8'))
clauses['16']=re.sub(r'\s+',' ',pages[74]+pages[75]+pages[76]).strip()
for n in range(1,6):
 key=f'4.5.{n}'
 match=re.search(re.escape(key)+r'\s+(.*?)(?=\n\s*4\.[56]\.\d+\.?\s|\n4\.6\.|\Z)',pages[40],re.S)
 assert match,key
 clauses[key]=re.sub(r'\s+',' ',match.group(1)).strip()
topics=[];items=[]
def topic(id,title,ref):
 topics.append(dict(id=id,title=title,sectionRef=ref,description='Практические правила: '+title.lower()+'. Изучите порядок действий, ограничения и исключения.'))
def rows(t,text,kind='question'):
 for line in text.strip().splitlines():
  if not line.strip():continue
  clause,q,a,wrong,why=line.split('|')
  assert clause in clauses,clause
  page=next((i+1 for i,p in enumerate(pages) if re.search(r'(?m)^\s*'+re.escape(clause)+r'\.?\s',p)),0)
  assert page,clause
  opts=[a]+wrong.split('~');assert len(opts)==4
  n=sum(x['topicId']==t and x['kind']==kind for x in items)+1
  items.append(dict(id=f'reg-{t}-{kind}-{n}',topicId=t,kind=kind,difficulty=['easy','medium','hard'][(n-1)%3] if kind=='question' else 'hard',question=q,wolfContext='Сценарий клиентского обслуживания. Выберите действие по регламенту.' if kind=='case' else 'Проверьте правило и разберите его применение.',options=opts,correctIndex=0,explanation=why,clauseRef=f'Регламент № 93, п. {clause} (стр. {page})',sourcePage=page,sourceClause=clause))

